records.command:
node --input-type=module <<'JS'
import {spawnSync,execFileSync} from 'node:child_process';
import {writeFileSync} from 'node:fs';
const file='apps/web/src/core/managers/commands.ts';
const original=execFileSync('git',['show','HEAD:classic/'+file],{encoding:'utf8'});
const opts={cwd:'classic',encoding:'utf8',maxBuffer:8*1024**2};
const before=spawnSync('node',['node_modules/eslint/bin/eslint.js','--stdin','--stdin-filename',file,'-f','json'],{...opts,input:original});
const after=spawnSync('node',['node_modules/eslint/bin/eslint.js',file,'-f','json'],opts);
const errors=r=>JSON.parse(r.stdout).flatMap(x=>x.messages).filter(x=>x.severity===2).map(({ruleId,message})=>({ruleId,message}));
const result={before:errors(before),after:errors(after)};
if(JSON.stringify(result.before)!==JSON.stringify(result.after))throw Error('New lint errors');
writeFileSync('.local/smart-takes-2026-10-29/lint-baseline.json',JSON.stringify(result));
console.log('No new lint errors; both pre-existing errors reproduced from HEAD.');
JS
